/* CSS PART 1 OF 4 */

/* =========================================================
   JOSH BROOKS CONSTRUCTION & RENOVATION
   Original design direction: Modern Colorado Craft
   Foundation: Design tokens, reset, typography and layout
   ========================================================= */

/* 01. DESIGN TOKENS
   --------------------------------------------------------- */

:root {
  color-scheme: light;

  /* Brand-inspired palette */
  --color-ink: #202b30;
  --color-ink-soft: #39474c;
  --color-charcoal: #182226;
  --color-slate: #65747a;
  --color-muted: #899497;

  --color-primary: #a94f36;
  --color-primary-dark: #843b2a;
  --color-primary-light: #d17a5e;

  --color-sand: #e9e2d7;
  --color-cream: #f7f5f0;
  --color-paper: #fffefa;
  --color-white: #ffffff;

  --color-border: #dedbd3;
  --color-border-dark: #c7c4bb;

  --color-success: #426b57;

  /* Typography */
  --font-heading: "DM Sans", "Helvetica Neue", Arial, sans-serif;
  --font-body: "Inter", "Helvetica Neue", Arial, sans-serif;
  --font-accent: Georgia, "Times New Roman", serif;

  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-md: 1.125rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: 2.75rem;
  --font-size-4xl: clamp(3rem, 6.2vw, 5.75rem);

  --line-height-tight: 1.08;
  --line-height-heading: 1.2;
  --line-height-body: 1.7;

  /* Spacing scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --container-width: 1240px;
  --container-narrow: 820px;
  --page-gutter: clamp(1.25rem, 5vw, 5rem);
  --section-space: clamp(4.5rem, 9vw, 8rem);
  --header-height: 88px;

  /* Image and surface treatments */
  --radius-sm: 4px;
  --radius-md: 9px;
  --radius-lg: 16px;
  --radius-pill: 999px;

  /* Shadows */
  --shadow-subtle: 0 3px 16px rgba(32, 43, 48, 0.06);
  --shadow-medium: 0 12px 35px rgba(32, 43, 48, 0.12);
  --shadow-heavy: 0 22px 60px rgba(24, 34, 38, 0.18);

  /* Motion */
  --transition-fast: 160ms ease;
  --transition-base: 260ms ease;
  --transition-slow: 450ms ease;
}


/* 02. RESET AND GLOBAL FOUNDATIONS
   --------------------------------------------------------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--header-height) + 20px);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  font-weight: 400;
  line-height: var(--line-height-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img,
picture,
video,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

button,
input,
select,
textarea {
  font: inherit;
}

button,
select {
  cursor: pointer;
}

button {
  color: inherit;
}

a {
  color: inherit;
  text-decoration: none;
}

p,
h1,
h2,
h3,
h4,
h5,
h6,
figure,
blockquote {
  margin-top: 0;
}

p:last-child {
  margin-bottom: 0;
}

ul,
ol {
  padding-left: 1.35em;
}

::selection {
  background: var(--color-primary);
  color: var(--color-white);
}


/* 03. ACCESSIBILITY FOUNDATIONS
   --------------------------------------------------------- */

:focus {
  outline: none;
}

:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: 9999;
  top: 12px;
  left: 12px;
  padding: 12px 18px;
  transform: translateY(-160%);
  border-radius: var(--radius-sm);
  background: var(--color-charcoal);
  color: var(--color-white);
  font-weight: 700;
  transition: transform var(--transition-fast);
}

.skip-link:focus {
  transform: translateY(0);
}

[hidden] {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}


/* 04. TYPOGRAPHY SYSTEM
   --------------------------------------------------------- */

h1,
h2,
h3,
h4,
h5,
h6 {
  margin-bottom: var(--space-5);
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-weight: 750;
  letter-spacing: -0.045em;
  line-height: var(--line-height-heading);
}

h1 {
  font-size: var(--font-size-4xl);
  letter-spacing: -0.065em;
  line-height: var(--line-height-tight);
}

h2 {
  font-size: clamp(2.1rem, 4vw, 3.5rem);
  letter-spacing: -0.055em;
}

h3 {
  font-size: clamp(1.35rem, 2.2vw, 1.8rem);
}

h4 {
  font-size: var(--font-size-lg);
  letter-spacing: -0.025em;
}

p {
  margin-bottom: var(--space-5);
  color: var(--color-slate);
  font-size: var(--font-size-base);
  line-height: var(--line-height-body);
}

strong,
b {
  color: var(--color-ink);
  font-weight: 700;
}

small {
  font-size: var(--font-size-sm);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: var(--space-5);
  color: var(--color-primary);
  font-size: var(--font-size-xs);
  font-weight: 800;
  letter-spacing: 0.16em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 28px;
  height: 2px;
  background: currentColor;
  content: "";
}

.display-heading {
  max-width: 900px;
  font-size: var(--font-size-4xl);
}

.section-heading {
  max-width: 760px;
  font-size: var(--font-size-3xl);
}

.lead {
  max-width: 680px;
  color: var(--color-ink-soft);
  font-size: clamp(1.05rem, 1.7vw, 1.25rem);
  line-height: 1.75;
}

.text-muted {
  color: var(--color-muted);
}

.text-primary {
  color: var(--color-primary);
}

.text-light {
  color: var(--color-white);
}

.text-light p {
  color: rgba(255, 255, 255, 0.76);
}


/* 05. PAGE GRID AND SHARED CONTAINERS
   --------------------------------------------------------- */

#page {
  width: 100%;
  overflow: clip;
}

.container {
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
}

.container--narrow {
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-narrow)
  );
  margin-inline: auto;
}

.container--wide {
  width: min(
    calc(100% - (var(--page-gutter) * 1.25)),
    1440px
  );
  margin-inline: auto;
}

.section {
  position: relative;
  padding-block: var(--section-space);
}

.section--compact {
  padding-block: clamp(3rem, 6vw, 5rem);
}

.section--cream {
  background: var(--color-cream);
}

.section--sand {
  background: var(--color-sand);
}

.section--dark {
  background: var(--color-charcoal);
  color: var(--color-white);
}

.section--dark h2,
.section--dark h3,
.section--dark h4 {
  color: var(--color-white);
}

.section-intro {
  max-width: 720px;
  margin-bottom: var(--space-12);
}

.section-intro p {
  max-width: 640px;
}


/* 06. SHARED GRID AND FLEX UTILITIES
   --------------------------------------------------------- */

.grid {
  display: grid;
  gap: var(--space-8);
}

.grid--2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid--3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid--4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.grid--asymmetric {
  grid-template-columns: 1.1fr 0.9fr;
  align-items: center;
  gap: clamp(2.5rem, 6vw, 6rem);
}

.flex {
  display: flex;
}

.flex--center {
  align-items: center;
  justify-content: center;
}

.flex--between {
  align-items: center;
  justify-content: space-between;
}

.flex--column {
  flex-direction: column;
}

.flex--wrap {
  flex-wrap: wrap;
}

.align-start {
  align-items: flex-start;
}

.align-center {
  align-items: center;
}

.gap-2 {
  gap: var(--space-2);
}

.gap-4 {
  gap: var(--space-4);
}

.gap-6 {
  gap: var(--space-6);
}

.gap-8 {
  gap: var(--space-8);
}


/* 07. SHARED SECTION ALIGNMENT
   --------------------------------------------------------- */

.text-center {
  text-align: center;
}

.text-center .section-intro,
.text-center .lead {
  margin-inline: auto;
}

.text-right {
  text-align: right;
}

.stack > * + * {
  margin-top: var(--space-4);
}

.stack--large > * + * {
  margin-top: var(--space-8);
}

.content-width {
  max-width: 720px;
}

.content-width--small {
  max-width: 560px;
}

.full-width {
  width: 100%;
}

.relative {
  position: relative;
}

.overflow-hidden {
  overflow: hidden;
}


/* 08. SHARED VISUAL DETAILS
   --------------------------------------------------------- */

/* Restrained construction-inspired dividing line */
.section-rule {
  width: 100%;
  height: 1px;
  border: 0;
  background: var(--color-border);
}

.section-rule--dark {
  background: rgba(255, 255, 255, 0.16);
}

/* Small architectural corner marker */
.corner-marker {
  position: relative;
}

.corner-marker::before {
  position: absolute;
  top: 0;
  left: 0;
  width: 26px;
  height: 3px;
  background: var(--color-primary);
  content: "";
}

/* Shared image foundation */
.image-frame {
  position: relative;
  overflow: hidden;
  background: var(--color-sand);
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-frame--landscape {
  aspect-ratio: 4 / 3;
}

.image-frame--portrait {
  aspect-ratio: 3 / 4;
}

.image-frame--wide {
  aspect-ratio: 16 / 9;
}


/* 09. RESPONSIVE FOUNDATIONS
   --------------------------------------------------------- */

@media (max-width: 1024px) {
  :root {
    --header-height: 76px;
    --section-space: clamp(4rem, 8vw, 6rem);
  }

  .grid--4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid--3 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .grid--asymmetric {
    gap: var(--space-10);
  }
}

@media (max-width: 680px) {
  :root {
    --page-gutter: 1.25rem;
    --section-space: 4rem;
    --header-height: 70px;

    --font-size-2xl: 1.75rem;
    --font-size-3xl: 2.15rem;
  }

  body {
    font-size: 0.95rem;
  }

  .grid--2,
  .grid--3,
  .grid--4,
  .grid--asymmetric {
    grid-template-columns: minmax(0, 1fr);
  }

  .section-intro {
    margin-bottom: var(--space-8);
  }

  .display-heading {
    font-size: clamp(2.8rem, 12vw, 4rem);
  }

  .section-heading {
    font-size: clamp(2rem, 9vw, 2.8rem);
  }

  .lead {
    font-size: 1.05rem;
  }

  .text-center-mobile {
    text-align: center;
  }

  .flex-mobile-column {
    flex-direction: column;
    align-items: stretch;
  }
}
