/* CSS PART 2 OF 4 */

/* =========================================================
   JOSH BROOKS CONSTRUCTION & RENOVATION
   Header, navigation, hero and primary conversion actions
   ========================================================= */


/* 01. SITE HEADER
   --------------------------------------------------------- */

.site-header {
  position: sticky;
  z-index: 1000;
  top: 0;
  width: 100%;
  background: var(--color-paper);
  border-bottom: 1px solid rgba(32, 43, 48, 0.09);
  box-shadow: 0 3px 18px rgba(32, 43, 48, 0.035);
}

.header-inner {
  display: flex;
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  min-height: var(--header-height);
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
}

.header-brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: var(--space-3);
  color: var(--color-ink);
  text-decoration: none;
}

.header-brand img {
  width: auto;
  max-width: 190px;
  max-height: 66px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-name {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 0.94rem;
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.2;
}

.brand-description {
  color: var(--color-slate);
  font-size: 0.65rem;
  font-weight: 650;
  letter-spacing: 0.1em;
  line-height: 1.4;
  text-transform: uppercase;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-5);
}

.header-phone {
  display: inline-flex;
  flex-direction: column;
  gap: 2px;
  color: var(--color-ink);
  font-size: var(--font-size-sm);
  font-weight: 750;
  line-height: 1.3;
}

.header-phone span:first-child {
  color: var(--color-muted);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.header-phone:hover {
  color: var(--color-primary);
}


/* 02. DESKTOP NAVIGATION
   --------------------------------------------------------- */

.main-navigation {
  display: flex;
  height: 100%;
  align-items: center;
}

.nav-list {
  display: flex;
  margin: 0;
  padding: 0;
  align-items: center;
  gap: clamp(1rem, 2vw, 1.9rem);
  list-style: none;
}

.nav-list li {
  position: relative;
  margin: 0;
}

.nav-list a {
  position: relative;
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  color: var(--color-ink-soft);
  font-size: 0.83rem;
  font-weight: 650;
  transition: color var(--transition-fast);
}

.nav-list a::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 2px;
  transform: scaleX(0);
  transform-origin: left;
  background: var(--color-primary);
  content: "";
  transition: transform var(--transition-base);
}

.nav-list a:hover,
.nav-list a:focus-visible,
.nav-list a[aria-current="page"] {
  color: var(--color-primary);
}

.nav-list a:hover::after,
.nav-list a:focus-visible::after,
.nav-list a[aria-current="page"]::after {
  transform: scaleX(1);
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown > a {
  gap: var(--space-2);
}

.nav-dropdown > a::before {
  width: 6px;
  height: 6px;
  margin-top: -3px;
  transform: rotate(45deg);
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  content: "";
}

.dropdown-menu {
  position: absolute;
  z-index: 20;
  top: calc(100% + 8px);
  left: -18px;
  display: none;
  width: 230px;
  margin: 0;
  padding: var(--space-3);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-paper);
  box-shadow: var(--shadow-medium);
  list-style: none;
}

.nav-dropdown:hover .dropdown-menu,
.nav-dropdown:focus-within .dropdown-menu,
.nav-dropdown[aria-expanded="true"] .dropdown-menu {
  display: block;
}

.dropdown-menu a {
  display: flex;
  width: 100%;
  min-height: 42px;
  padding-inline: var(--space-3);
  border-radius: var(--radius-sm);
  color: var(--color-ink-soft);
}

.dropdown-menu a::after {
  display: none;
}

.dropdown-menu a:hover,
.dropdown-menu a:focus-visible {
  background: var(--color-cream);
  color: var(--color-primary);
}


/* 03. MOBILE NAVIGATION CONTROLS
   --------------------------------------------------------- */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  padding: 10px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--color-ink);
}

.menu-toggle span {
  display: block;
  width: 20px;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transition:
    transform var(--transition-base),
    opacity var(--transition-base);
}

.menu-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(7px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-7px) rotate(-45deg);
}


/* 04. PRIMARY BUTTON SYSTEM
   --------------------------------------------------------- */

.button {
  display: inline-flex;
  min-height: 54px;
  padding: 0 var(--space-8);
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--color-primary);
  color: var(--color-white);
  font-family: var(--font-heading);
  font-size: 0.9rem;
  font-weight: 750;
  letter-spacing: 0.005em;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  transition:
    background var(--transition-base),
    border-color var(--transition-base),
    color var(--transition-base),
    box-shadow var(--transition-base),
    transform var(--transition-base);
}

.button:hover {
  transform: translateY(-2px);
  background: var(--color-primary-dark);
  box-shadow: 0 8px 20px rgba(132, 59, 42, 0.2);
  color: var(--color-white);
}

.button:active {
  transform: translateY(0);
}

.button--small {
  min-height: 44px;
  padding-inline: var(--space-5);
  font-size: 0.82rem;
}

.button--large {
  min-height: 62px;
  padding-inline: var(--space-10);
  font-size: 1rem;
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  background: transparent;
  color: var(--color-white);
}

.button--outline:hover {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-ink);
}

.button--dark {
  background: var(--color-charcoal);
  color: var(--color-white);
}

.button--dark:hover {
  background: var(--color-ink-soft);
}

.button--light {
  border-color: var(--color-border);
  background: var(--color-paper);
  color: var(--color-ink);
}

.button--light:hover {
  border-color: var(--color-primary);
  background: var(--color-cream);
  color: var(--color-primary);
}

.button:disabled,
.button[aria-disabled="true"] {
  transform: none;
  cursor: not-allowed;
  opacity: 0.55;
  box-shadow: none;
}

.button-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-4);
}


/* 05. HERO SECTION
   --------------------------------------------------------- */

.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - var(--header-height)));
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--color-charcoal);
  color: var(--color-white);
}

.hero-background {
  position: absolute;
  z-index: -2;
  inset: 0;
}

.hero-background img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 46%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(18, 28, 31, 0.92) 0%,
      rgba(18, 28, 31, 0.79) 43%,
      rgba(18, 28, 31, 0.25) 100%
    ),
    linear-gradient(
      0deg,
      rgba(18, 28, 31, 0.28),
      transparent 50%
    );
  content: "";
}

.hero-inner {
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
  padding-block: clamp(5rem, 10vw, 9rem);
}

.hero-content {
  max-width: 760px;
}

.hero .eyebrow {
  color: #e5a087;
}

.hero h1 {
  max-width: 760px;
  margin-bottom: var(--space-6);
  color: var(--color-white);
}

.hero-description {
  max-width: 620px;
  margin-bottom: var(--space-8);
  color: rgba(255, 255, 255, 0.86);
  font-size: clamp(1.05rem, 1.6vw, 1.25rem);
  line-height: 1.75;
}

.hero .button-group {
  margin-top: var(--space-8);
}

.hero-note {
  display: flex;
  margin-top: var(--space-6);
  align-items: center;
  gap: var(--space-3);
  color: rgba(255, 255, 255, 0.8);
  font-size: var(--font-size-sm);
}

.hero-note::before {
  width: 26px;
  height: 1px;
  flex: 0 0 auto;
  background: var(--color-primary-light);
  content: "";
}


/* 06. HERO IMAGE DETAIL AND CAPTION
   --------------------------------------------------------- */

.hero-caption {
  position: absolute;
  right: var(--page-gutter);
  bottom: var(--space-6);
  max-width: 250px;
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.72rem;
  line-height: 1.5;
  text-align: right;
}

.hero-caption strong {
  display: block;
  margin-bottom: 3px;
  color: var(--color-white);
  font-size: 0.78rem;
}


/* 07. TRUST AND CONTACT STRIP
   --------------------------------------------------------- */

.hero-trust-strip {
  position: relative;
  z-index: 2;
  background: var(--color-cream);
  border-bottom: 1px solid var(--color-border);
}

.hero-trust-inner {
  display: grid;
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: stretch;
}

.trust-item {
  display: flex;
  min-height: 104px;
  padding: var(--space-5) var(--space-6);
  flex-direction: column;
  justify-content: center;
  border-right: 1px solid var(--color-border);
}

.trust-item:first-child {
  padding-left: 0;
}

.trust-item:last-child {
  border-right: 0;
}

.trust-label {
  margin-bottom: var(--space-1);
  color: var(--color-muted);
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.trust-value {
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 750;
  line-height: 1.4;
}


/* 08. MOBILE HERO CONVERSION BAR
   --------------------------------------------------------- */

.mobile-contact-bar {
  display: none;
  position: fixed;
  z-index: 900;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 10px var(--page-gutter);
  background: var(--color-paper);
  border-top: 1px solid var(--color-border);
  box-shadow: 0 -5px 20px rgba(32, 43, 48, 0.09);
}

.mobile-contact-bar .button {
  width: 100%;
  min-height: 50px;
}


/* 09. TABLET NAVIGATION
   --------------------------------------------------------- */

@media (max-width: 1100px) {
  .header-inner {
    gap: var(--space-4);
  }

  .nav-list {
    gap: var(--space-4);
  }

  .nav-list a {
    font-size: 0.77rem;
  }

  .header-brand img {
    max-width: 155px;
  }

  .header-phone {
    display: none;
  }
}


/* 10. MOBILE NAVIGATION AND HERO
   --------------------------------------------------------- */

@media (max-width: 820px) {
  .menu-toggle {
    display: flex;
    flex: 0 0 auto;
  }

  .main-navigation {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    height: auto;
    padding: var(--space-4) var(--page-gutter) var(--space-6);
    border-top: 1px solid var(--color-border);
    background: var(--color-paper);
    box-shadow: var(--shadow-medium);
  }

  .main-navigation.is-open {
    display: block;
  }

  .nav-list {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }

  .nav-list li {
    width: 100%;
    border-bottom: 1px solid var(--color-border);
  }

  .nav-list a {
    display: flex;
    width: 100%;
    min-height: 48px;
    padding-inline: var(--space-2);
    font-size: 0.95rem;
  }

  .nav-list a::after {
    display: none;
  }

  .nav-dropdown > a {
    justify-content: space-between;
  }

  .dropdown-menu {
    position: static;
    display: none;
    width: 100%;
    padding: 0 var(--space-3) var(--space-3);
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }

  .nav-dropdown:hover .dropdown-menu {
    display: none;
  }

  .nav-dropdown[aria-expanded="true"] .dropdown-menu {
    display: block;
  }

  .dropdown-menu a {
    min-height: 42px;
    padding-left: var(--space-4);
    font-size: 0.88rem;
  }

  .header-actions {
    margin-left: auto;
  }

  .hero {
    min-height: 640px;
    min-height: min(760px, calc(100svh - var(--header-height)));
  }

  .hero::before {
    background:
      linear-gradient(
        90deg,
        rgba(18, 28, 31, 0.88),
        rgba(18, 28, 31, 0.52)
      ),
      linear-gradient(
        0deg,
        rgba(18, 28, 31, 0.45),
        transparent 65%
      );
  }

  .hero-inner {
    padding-block: 5.5rem;
  }

  .hero-content {
    max-width: 680px;
  }
}


/* 11. SMALL MOBILE REFINEMENTS
   --------------------------------------------------------- */

@media (max-width: 580px) {
  .header-inner {
    min-height: 68px;
  }

  .header-brand {
    gap: var(--space-2);
  }

  .header-brand img {
    max-width: 125px;
    max-height: 52px;
  }

  .brand-name {
    font-size: 0.8rem;
  }

  .brand-description {
    font-size: 0.57rem;
  }

  .hero {
    min-height: 680px;
    min-height: min(780px, calc(100svh - var(--header-height)));
  }

  .hero-background img {
    object-position: 60% center;
  }

  .hero::before {
    background:
      linear-gradient(
        180deg,
        rgba(18, 28, 31, 0.48) 0%,
        rgba(18, 28, 31, 0.83) 52%,
        rgba(18, 28, 31, 0.94) 100%
      );
  }

  .hero-inner {
    padding-block: 4.5rem;
  }

  .hero h1 {
    font-size: clamp(2.65rem, 12vw, 3.65rem);
  }

  .hero-description {
    font-size: 1rem;
  }

  .hero .button-group {
    align-items: stretch;
    flex-direction: column;
  }

  .hero .button-group .button {
    width: 100%;
  }

  .hero-caption {
    display: none;
  }

  .hero-trust-inner {
    grid-template-columns: 1fr;
  }

  .trust-item {
    min-height: 76px;
    padding: var(--space-4) 0;
    border-right: 0;
    border-bottom: 1px solid var(--color-border);
  }

  .trust-item:last-child {
    border-bottom: 0;
  }

  .mobile-contact-bar {
    display: block;
  }

  body {
    padding-bottom: 72px;
  }
}


/* 12. MOTION AND HIGH CONTRAST
   --------------------------------------------------------- */

@media (prefers-reduced-motion: no-preference) {
  .hero-content > * {
    animation: hero-enter 650ms ease both;
  }

  .hero-content > *:nth-child(2) {
    animation-delay: 100ms;
  }

  .hero-content > *:nth-child(3) {
    animation-delay: 180ms;
  }

  .hero-content > *:nth-child(4) {
    animation-delay: 260ms;
  }

  @keyframes hero-enter {
    from {
      opacity: 0;
      transform: translateY(16px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

@media (forced-colors: active) {
  .button,
  .menu-toggle,
  .nav-list a {
    border: 1px solid ButtonText;
  }

  .hero::before {
    background: rgba(0, 0, 0, 0.8);
  }
}
